#[cfg(not(all(target_arch = "wasm32", target_env = "p2")))]
fn render_to_svg(box_: &crate::math::MathBox, options: SnippetOptions) -> SvgSnippet {
    let f = fonts();
    let svg_ctx = SvgFontSet { math: &f.math, serif: &f.serif, mono: &f.mono };
