//#region 🔖️Escape
/// 🔐️ The ONE canonical escape scheme for quoted `Text` tokens: `\\ \" \n \r \t` plus
/// `\u{XXXX}` for any other control character. Nesting-sound because quoting is a token
/// boundary — re-escaping an already-printed line is exactly invertible, no percent-encoding
/// or per-technology scheme needed. Strict superset of every hand-rolled scheme it replaces.
// 🚫️async: E1 pure, inlined directly into `format!` args at every call site (Display, not Future) — see R9
pub fn escape_text(value: &str) -> String {
    let mut out = String::with_capacity(value.len());
    for ch in value.chars() {
        match ch {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{{{:x}}}", c as u32)),
            c => out.push(c),
        }
    }
    out
}

/// 🔓️ Inverse of [`escape_text`]. Unknown escapes in strict mode are an error; `forgiving`
/// keeps the backslash and following character literal instead (editor/recovery mode).
pub fn unescape_text(value: &str, forgiving: bool) -> Result<String, String> {
    let mut out = String::with_capacity(value.len());
    let mut chars = value.chars().peekable();
    while let Some(ch) = chars.next() {
        if ch != '\\' {
            out.push(ch);
            continue;
        }
        match chars.next() {
            Some('n') => out.push('\n'),
            Some('r') => out.push('\r'),
            Some('t') => out.push('\t'),
            Some('"') => out.push('"'),
            Some('\\') => out.push('\\'),
            Some('u') if chars.peek() == Some(&'{') => {
                chars.next();
                let mut hex = String::new();
                loop {
                    match chars.next() {
                        Some('}') => break,
                        Some(c) => hex.push(c),
                        None => return Err("unterminated \\u{...} escape".into()),
                    }
                }
                let code = u32::from_str_radix(&hex, 16).map_err(|_| format!("invalid unicode escape \\u{{{hex}}}"))?;
                let c = char::from_u32(code).ok_or_else(|| format!("invalid unicode scalar \\u{{{hex}}}"))?;
                out.push(c);
            }
            Some(other) => {
                if forgiving {
                    out.push('\\');
                    out.push(other);
                } else {
                    return Err(format!("unknown escape \\{other}"));
                }
            }
            None => {
                if forgiving {
                    out.push('\\');
                } else {
                    return Err("dangling escape at end of text".into());
                }
            }
        }
    }
    Ok(out)
}
//#endregion 🔖️Escape

//#region 🔖️Numbers
/// 🔢️ Float text preserves each NaN word and finite shortest-round-trip values.
// 🚫️async: E1 pure Display formatting consumed by `dsl_schema::print_expr_prec`, itself forced sync by an
// `Iterator::map(...).join(...)` sync-closure consumer (`Call` arm) — see R9
pub fn format_f64(value: f64) -> String {
    if value.is_nan() {
        format!("nan64_{:016x}",value.to_bits())
    } else if value.is_infinite() {
        if value > 0.0 {
            "inf".to_string()
        } else {
            "-inf".to_string()
        }
    } else {
        format!("{value}")
    }
}

pub fn format_f32(value: f32) -> String {
    if value.is_nan() {
        format!("nan32_{:08x}",value.to_bits())
    } else if value.is_infinite() {
        if value > 0.0 {
            "inf".to_string()
        } else {
            "-inf".to_string()
        }
    } else {
        format!("{value}")
    }
}

pub fn parse_f64(text: &str) -> Result<f64, String> {
    if let Some(word)=text.strip_prefix("nan64_"){if word.len()!=16||!word.bytes().all(|byte|byte.is_ascii_hexdigit()){return Err("invalid binary64 NaN word".into());}let bits=u64::from_str_radix(word,16).map_err(|error|error.to_string())?;if bits&0x7ff0000000000000!=0x7ff0000000000000||bits&0xfffffffffffff==0{return Err("binary64 NaN literal requires a NaN word".into());}return Ok(f64::from_bits(bits));}
    match text {
        "nan" => Ok(f64::NAN),
        "inf" => Ok(f64::INFINITY),
        "-inf" => Ok(f64::NEG_INFINITY),
        other => other.parse::<f64>().map_err(|_| format!("invalid float literal '{other}'")),
    }
}

pub fn parse_f32(text: &str) -> Result<f32, String> {
    if let Some(word)=text.strip_prefix("nan32_"){if word.len()!=8||!word.bytes().all(|byte|byte.is_ascii_hexdigit()){return Err("invalid binary32 NaN word".into());}let bits=u32::from_str_radix(word,16).map_err(|error|error.to_string())?;if bits&0x7f800000!=0x7f800000||bits&0x7fffff==0{return Err("binary32 NaN literal requires a NaN word".into());}return Ok(f32::from_bits(bits));}
    match text {
        "nan" => Ok(f32::NAN),
        "inf" => Ok(f32::INFINITY),
        "-inf" => Ok(f32::NEG_INFINITY),
        other => other.parse::<f32>().map_err(|_| format!("invalid float literal '{other}'")),
    }
}
//#endregion 🔖️Numbers

