//! 🕸️ Exact persisted Workflow ownership through sixteen handcrafted relational tables.
use super::{WorkflowSnapshot,Workflow,WorkflowNode,WorkflowEdge,WorkflowMediaPort,MediaContract,WorkflowParameter,WorkflowParameterBinding,WorkflowInput,WorkflowInputBinding,WorkflowOutputBinding};
use std::collections::BTreeMap;
use store::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteRow,SqliteValue,SqliteSnapshotControl,SqliteSnapshotPhase,SnapshotEncoding,validate_sqlite_database_schema,artifact::{Projection,Cell,FloatColumn,insert_ieee754,read_binary64,ieee754_is_null}}};
const NODE_GEOMETRY:&[FloatColumn]=&[FloatColumn::Binary64(10),FloatColumn::Binary64(11),FloatColumn::Binary64(12),FloatColumn::Binary64(13)];
const NUMERIC:&[FloatColumn]=&[FloatColumn::Binary64(2),FloatColumn::Binary64(3),FloatColumn::Binary64(4),FloatColumn::Binary64(5)];
fn add(total:usize,count:usize)->Result<usize,String>{total.checked_add(count).ok_or_else(||"Workflow semantic row count overflow".into())}
fn ordinal(index:usize)->Result<i64,String>{i64::try_from(index).map_err(|_|"Workflow ordinal exceeds INTEGER width".into())}
fn workload(value:&WorkflowSnapshot,control:&mut SqliteSnapshotControl<'_>,phase:SqliteSnapshotPhase)->Result<usize,String>{
 let units=add(value.graph.nodes.len(),value.parameters.len())?;control.checkpoint(phase,0,units)?;
 let mut count=2usize;for size in[value.graph.nodes.len(),value.graph.edges.len(),value.graph.edges.len(),value.parameters.len(),value.parameters.len(),value.parameter_bindings.len(),value.inputs.len(),value.input_bindings.len(),value.output_bindings.len()]{count=add(count,size)?}control.check_rows(count)?;
 for(index,node)in value.graph.nodes.iter().enumerate(){count=add(add(count,node.inputs.len())?,node.outputs.len())?;control.check_rows(count)?;if(index+1)%256==0{control.checkpoint(phase,index+1,units)?}}
 for(index,parameter)in value.parameters.iter().enumerate(){if let WorkflowParameter::Categorical{options,..}=parameter{count=add(count,options.len())?;control.check_rows(count)?}let completed=add(value.graph.nodes.len(),index+1)?;if completed%256==0{control.checkpoint(phase,completed,units)?}}
 control.checkpoint(phase,units,units)?;Ok(count)
}
fn entity(row:&SqliteRow,columns:usize)->Result<(),String>{if row.rowid<=0||row.values.len()!=columns||row.integer(0)?!=row.rowid{return Err("Workflow entities require complete columns and positive aliased identities".into())}Ok(())}
fn ordered<'a>(rows:&[&'a SqliteRow],columns:usize,slot:usize,native:&mut dsl::NativeDecodeControl<'_>)->Result<Vec<&'a SqliteRow>,String>{
 native.scoped_stage(|native|->Result<_,String>{native.begin_stage(rows.len())?;let mut slots=native.allocate_vec::<Option<&SqliteRow>>(rows.len())?;slots.resize(rows.len(),None);let mut ids=BTreeMap::new();for row in rows{entity(row,columns)?;let index=usize::try_from(row.integer(slot)?).map_err(|_|"Workflow ordinal must be nonnegative")?;if index>=slots.len()||slots[index].replace(*row).is_some()||ids.insert(row.rowid,()).is_some(){return Err("Workflow entity identities must be unique and collection ordinals dense".into())}native.step()?}let mut result=native.allocate_vec::<&SqliteRow>(slots.len())?;for row in slots{result.push(row.ok_or("Workflow ordinal is missing")?)}Ok(result)})
}
fn parent_rows<'a>(rows:&'a[SqliteRow],parent:i64,columns:usize,native:&mut dsl::NativeDecodeControl<'_>)->Result<Vec<&'a SqliteRow>,String>{
 native.scoped_stage(|native|->Result<_,String>{native.begin_stage(rows.len())?;let mut references=native.allocate_vec::<&SqliteRow>(rows.len())?;for row in rows{if row.integer(1)?!=parent{return Err("Workflow child has an unknown parent".into())}references.push(row);native.step()?}ordered(&references,columns,2,native)})
}
fn single_rows<'a>(rows:&'a[SqliteRow],columns:usize,native:&mut dsl::NativeDecodeControl<'_>)->Result<BTreeMap<i64,&'a SqliteRow>,String>{
 native.scoped_stage(|native|->Result<_,String>{native.begin_stage(rows.len())?;let mut result=BTreeMap::new();let mut ids=BTreeMap::new();for row in rows{entity(row,columns)?;if result.insert(row.integer(1)?,row).is_some()||ids.insert(row.rowid,()).is_some(){return Err("Workflow branch must have one unique entity per parent".into())}native.step()?}Ok(result)})
}
fn grouped<'a>(rows:&'a[SqliteRow],columns:usize,native:&mut dsl::NativeDecodeControl<'_>)->Result<BTreeMap<i64,Vec<&'a SqliteRow>>,String>{
 native.scoped_stage(|native|->Result<_,String>{native.begin_stage(rows.len())?;let mut result:BTreeMap<i64,Vec<&SqliteRow>>=BTreeMap::new();let mut ids=BTreeMap::new();for row in rows{entity(row,columns)?;if ids.insert(row.rowid,()).is_some(){return Err("Workflow relationship entity identity is duplicated".into())}result.entry(row.integer(1)?).or_default().push(row);native.step()?}Ok(result)})
}
fn boolean(value:i64)->Result<bool,String>{match value{0=>Ok(false),1=>Ok(true),_=>Err("Workflow flag must be zero or one".into())}}
fn enum32(value:i64)->Result<u32,String>{u32::try_from(value).map_err(|_|"Workflow enum must be an unsigned ordinal".into())}
