//! 🛫️ Declared native record output with one caller-owned cumulative controller.
use crate::os_dsl::NativeEncodeControl;
use crate::os_dsl::RecordSpecProducer;
use crate::os_dsl::RecordValue;
use semio_framework_diagnostic::TextError;
use crate::os_dsl::JoinMode;
