macro_rules! expansion_owner {
    ($owner:ty, $($guard:item)*) => {
        impl ArtifactDsl for $owner {
            const EXTENSION: &'static str = "expansion";
            fn parse_dsl(text: &str) -> Result<Self, TextError> { Ok(Self { output_bytes: text.len() }) }
            fn print_dsl(&self) -> String { ENCODER_CALLS.with(|count| count.set(count.get() + 1)); "x".repeat(self.output_bytes) }
        }
        impl ArtifactPack for $owner {
            fn encode_pack_with(&self, _: &PackEncodeOptions) -> Result<Vec<u8>, PackError> { ENCODER_CALLS.with(|count| count.set(count.get() + 1)); Ok(vec![120; self.output_bytes]) }
            fn decode_pack_with(bytes: &[u8], _: &PackDecodeOptions) -> Result<Self, PackError> { Ok(Self { output_bytes: bytes.len() }) }
        }
        impl ArtifactSqliteSnapshot for $owner {
            const SQLITE_SCHEMA: &'static str = include_str!("../🧬️schema/🗄️.sql");
            fn to_sqlite_database(&self, control: &mut SqliteSnapshotControl<'_>) -> Result<SqliteDatabase, String> {
                control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot, 0, 1)?;
                let mut database = SqliteDatabase::from_schema(Self::SQLITE_SCHEMA).map_err(|error| error.to_string())?;
                database.table_mut("encoding_expansion")?.rows.push(SqliteRow { rowid: 1, values: vec![SqliteValue::Integer(1), SqliteValue::Integer(i64::try_from(self.output_bytes).map_err(|error| error.to_string())?)] });
                Ok(database)
            }
            fn from_sqlite_database(database: &SqliteDatabase, control: &mut SqliteSnapshotControl<'_>) -> Result<Self, String> {
                control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot, 0, 1)?;
                Ok(Self { output_bytes: usize::try_from(database.table("encoding_expansion")?.rows[0].integer(1)?).map_err(|error| error.to_string())? })
            }
            $($guard)*
        }
    };
}
expansion_owner!(MissingEncodingGuard,);
expansion_owner!(MissingControlledEncoding,
    fn preflight_sqlite_snapshot_encoding(&self, _: SnapshotEncoding, control: &mut SqliteSnapshotControl<'_>) -> Result<(), String> {
        let mut bound=NativeEncodingBound::new(control)?;bound.add(self.output_bytes)?;bound.finish()
    }
);
expansion_owner!(GuardedEncoding,
    fn encode_sqlite_snapshot_native(&self, encoding: SnapshotEncoding, control: &mut SqliteSnapshotControl<'_>) -> Result<crate::io_schema::IoPayload, String> {
        use semio_framework_value::native_encoding::{NativeEncodeControl, NativeEncodeProgress};
        let limits=control.limits();if self.output_bytes>limits.max_file_bytes{return Err("native fixture exceeds file ceiling".into())}let mut callback=|event:NativeEncodeProgress|control.checkpoint(SqliteSnapshotPhase::EncodeNative,event.completed,event.total).is_ok();let mut native=NativeEncodeControl::new(limits.max_value_bytes,&mut callback);native.begin_stage(self.output_bytes)?;let mut bytes=native.allocate_vec(self.output_bytes)?;CONTROLLED_ENCODER_CALLS.with(|count|count.set(count.get()+1));while bytes.len()<self.output_bytes{let count=65536.min(self.output_bytes-bytes.len());bytes.resize(bytes.len()+count,b'x');native.advance(count)?;}match encoding{SnapshotEncoding::Binary=>Ok(crate::io_schema::IoPayload::Binary(bytes)),SnapshotEncoding::Text=>Ok(crate::io_schema::IoPayload::Text(String::from_utf8(bytes).map_err(|error|error.to_string())?))}
    }
    fn preflight_sqlite_snapshot_encoding(&self, _: SnapshotEncoding, control: &mut SqliteSnapshotControl<'_>) -> Result<(), String> {
        let mut bound = NativeEncodingBound::new(control)?;
        bound.add(self.output_bytes)?;
        bound.finish()
    }
);
expansion_owner!(EstimatedEncoding,
    fn encode_sqlite_snapshot_native(&self,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<crate::io_schema::IoPayload,String>{GuardedEncoding{output_bytes:self.output_bytes}.encode_sqlite_snapshot_native(encoding,control)}
    fn preflight_sqlite_snapshot_encoding(&self,_:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),String>{
        let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let mut bound=NativeEncodingBound::new(control)?;bound.repeated(self.output_bytes,fixture["exactEncodingAdmission"]["estimateMultiplier"].as_u64().unwrap()as usize)?;bound.finish()
