    fn to_value(&self) -> crate::value::DslValue {
        crate::value::DslValue::object(vec![("id".to_string(), crate::value::ToValue::to_value(&self.id)), ("tool".to_string(), crate::value::ToValue::to_value(&self.tool))])
    }
