async fn fs_storage(name: &str) -> (StdArc<db_storage::DbBackend>, std::path::PathBuf) {
    let dir = std::env::temp_dir().join(format!("db_artifact_{name}_{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
