        self.0.descriptor()
    }

    fn diff(&self, base: &DemoSnapshot) -> crate::os_spr::MutationOutcome<Self::Diff> {
        COUNTED_FOLDS.with(|folds| folds.set(folds.get() + 1));
        self.0.diff(base)
    }

