pub(crate) struct SetTransactionCountWithoutPreflight {
    pub value: i32,
}
impl SetTransactionCountWithoutPreflight {
    const OPCODE: &'static str = "set-transaction-count-without-preflight";
    const TAG: u8 = 0x63;
}
impl OpText for SetTransactionCountWithoutPreflight {
    fn parse_op(line: &str) -> Result<Self, semio_framework_diagnostic::TextError> {
        Ok(Self {
            value: line
                .strip_prefix("set-transaction-count-without-preflight ")
                .ok_or_else(|| semio_framework_diagnostic::TextError::new("expected set-transaction-count-without-preflight", semio_framework_diagnostic::TextSpan::at(1, 1)))?
                .parse()
                .map_err(|_| semio_framework_diagnostic::TextError::new("transaction count must be i32", semio_framework_diagnostic::TextSpan::at(1, 1)))?,
        })
    }
    fn print_op(&self) -> String {
        format!("{} {}", Self::OPCODE, self.value)
    }
}
impl OpBinary for SetTransactionCountWithoutPreflight {
    fn encode_op(&self) -> Result<Vec<u8>, ProtocolError> {
        let mut bytes = vec![Self::TAG];
        bytes.extend_from_slice(&self.value.to_be_bytes());
        Ok(bytes)
    }
    fn decode_op(bytes: &[u8]) -> Result<Self, ProtocolError> {
        if bytes.len() != 5 || bytes.first() != Some(&Self::TAG) {
            return Err(ProtocolError::Malformed { what: "set-transaction-count-without-preflight", offset: 0, detail: "expected tag 0x63 and four i32 bytes".into() });
        }
        Ok(Self { value: i32::from_be_bytes(bytes[1..].try_into().expect("exact i32 width")) })
    }
}
impl MutationKind<TxnSnapshot, TxnMutation> for SetTransactionCountWithoutPreflight {
    const SEMANTICS: SemanticDescriptor = SemanticDescriptor { verb: "set", entity: "transaction-count-without-preflight", kind: "set-transaction-count-without-preflight", record: "SetTransactionCountWithoutPreflight" };
    fn diff(&self, _: &TxnSnapshot) -> MutationOutcome<TxnDiff> {
        MutationOutcome::new(TxnDiff { count: Some(self.value) })
    }
    fn inverse(&self, base: &TxnSnapshot) -> Vec<TxnMutation> {
        vec![SetTransactionCount { value: base.count }.into()]
    }
    fn label(&self) -> semio_framework_ui_locale::LocalizedLabel {
        semio_framework_ui_locale::LocalizedLabel::native(&format!("Set transaction count without preflight to {}", self.value), &format!("Transaktionsanzahl ohne Vorprüfung auf {} setzen", self.value))
    }
    fn foreign_steps(&self, _: &TxnSnapshot) -> Vec<protocol::ForeignStep> {
        panic!("no-foreign mutations must bypass foreign-step preflight")
    }
