        pub fault: Option<Fault>,
    }

    struct PeerRosterCandidate<P> {
        seq: u64,
        generation: u64,
        cancel: semio_framework_job::CancelToken,
        own_color: Option<u8>,
        now_ms: i64,
        root: std::sync::Arc<PeerPresenceRoot>,
