    pub fn install_plugin_bundle<PA: PluginApp>(runtime: &PluginRuntime<PA>, bundle: Plugin<PA>) {
        *runtime.plugin.borrow_mut() = Some(bundle);
        *runtime.plugin_assembly_error.borrow_mut() = None;
