                version: "0.0.0".into(),
                apps: vec![],
                examples: vec![],
                capabilities: vec![],
                topic_contributions: vec![],
                commands: vec![],
                artifact_kinds: vec![],
                hosted_artifact_kinds: Vec::new(),
                dependencies: vec![],
                contributions: vec![],
            },
            Plugin::manifest,
        )
    }

