        <TestMutation as protocol::FromValue>::from_value(value).map(Self)
    }
}

impl ::protocol::OpBinary for ReloadCountedOp {
    fn encode_op(&self) -> Result<Vec<u8>, ::protocol::ProtocolError> {
        ::protocol::OpBinary::encode_op(&self.0)
    }

